334	    bool WebSocketTransport::closingDelayExceeded()
335	    {
336	        std::lock_guard<std::mutex> lock(_closingTimePointMutex);
337	        auto now = std::chrono::steady_clock::now();
338	        return now - _closingTimePoint > std::chrono::milliseconds(kClosingMaximumWaitingDelayInMs);
339	    }
340	
341	    WebSocketTransport::PollResult WebSocketTransport::poll()
342	    {
343	        if (_readyState == ReadyState::OPEN)
344	        {
345	            if (pingIntervalExceeded())
346	            {
347	                // If it is not a 'ping' message of ping type, there is no need to judge whether
348	                // pong will receive it
349	                if (_pingType == SendMessageKind::Ping && !_pongReceived)
350	                {
351	                    // ping response (PONG) exceeds the maximum delay, close the connection
352	                    close(WebSocketCloseConstants::kInternalErrorCode,
353	                          WebSocketCloseConstants::kPingTimeoutMessage);
354	                }
355	                else
356	                {
357	                    sendHeartBeat(_pingType);
358	                }
359	            }
360	        }
361	
362	        // No timeout if state is not OPEN, otherwise computed
363	        // pingIntervalOrTimeoutGCD (equals to -1 if no ping and no ping timeout are set)
364	        int lastingTimeoutDelayInMs = (_readyState != ReadyState::OPEN) ? 0 : _pingIntervalSecs;
365	
366	        if (_pingIntervalSecs > 0)
367	        {
368	            // compute lasting delay to wait for next ping / timeout, if at least one set
369	            auto now = std::chrono::steady_clock::now();
370	            int timeSinceLastPingMs = (int) std::chrono::duration_cast<std::chrono::milliseconds>(
371	                                          now - _lastSendPingTimePoint)
372	                                          .count();
373	            lastingTimeoutDelayInMs = (1000 * _pingIntervalSecs) - timeSinceLastPingMs;
374	        }
375	
376	        // The platform may not have select interrupt capabilities, so wait with a small timeout
377	        if (lastingTimeoutDelayInMs <= 0 && !_socket->isWakeUpFromPollSupported())
378	        {
379	            lastingTimeoutDelayInMs = 20;
380	        }
381	
382	        // If we are requesting a cancellation, pass in a positive and small timeout
383	        // to never poll forever without a timeout.
384	        if (_requestInitCancellation)
385	        {
386	            lastingTimeoutDelayInMs = 100;
387	        }
388	
389	        // poll the socket
390	        PollResultType pollResult = _socket->isReadyToRead(lastingTimeoutDelayInMs);
391	
392	        // Make sure we send all the buffered data
393	        // there can be a lot of it for large messages.
394	        if (pollResult == PollResultType::SendRequest)
395	        {
396	            if (!flushSendBuffer())
397	            {
398	                return PollResult::CannotFlushSendBuffer;
399	            }
400	        }
401	        else if (pollResult == PollResultType::ReadyForRead)
402	        {
403	            if (!receiveFromSocket())
404	            {
405	                return PollResult::AbnormalClose;
406	            }
407	        }
408	        else if (pollResult == PollResultType::Error)
409	        {
410	            closeSocket();
411	        }
412	        else if (pollResult == PollResultType::CloseRequest)
413	        {
414	            closeSocket();
415	        }
416	
417	        if (_readyState == ReadyState::CLOSING && closingDelayExceeded())
418	        {
419	            _rxbuf.clear();
420	            // close code and reason were set when calling close()
421	            closeSocket();
422	            setReadyState(ReadyState::CLOSED);
423	        }
424	
425	        return PollResult::Succeeded;
426	    }
