838	    void WebSocketTransport::emitMessage(MessageKind messageKind,
839	                                         const std::string& message,
840	                                         bool compressedMessage,
841	                                         const OnMessageCallback& onMessageCallback)
842	    {
843	        size_t wireSize = message.size();
844	
845	        // When the RSV1 bit is 1 it means the message is compressed
846	        if (compressedMessage && messageKind != MessageKind::FRAGMENT)
847	        {
848	            bool success = _perMessageDeflate->decompress(message, _decompressedMessage);
849	
850	            if (!success)
851	            {
852	                // The compressed payload is invalid: the whole message
853	                // fails. It must not be delivered, not even the partially
854	                // decompressed content; the caller is notified with an
855	                // error instead, and the connection is closed.
856	                //
857	                // Drop every incoming frame from then on, except CLOSE
858	                // frames which are still processed to complete the closing
859	                // handshake.
860	                _protocolError = true;
861	
862	                // Close first, so that the connection is already closing
863	                // when the error is emitted (sending from the error
864	                // callback will fail).
865	                close(WebSocketCloseConstants::kInvalidFramePayloadData,
866	                      WebSocketCloseConstants::kDecompressionErrorMessage);
867	
868	                _decompressedMessage.clear();
869	                onMessageCallback(_decompressedMessage, wireSize, true, messageKind);
870	                return;
871	            }
872	
873	            if (messageKind == MessageKind::MSG_TEXT && !validateUtf8(_decompressedMessage))
874	            {
875	                close(WebSocketCloseConstants::kInvalidFramePayloadData,
876	                      WebSocketCloseConstants::kInvalidFramePayloadDataMessage);
877	            }
878	            else
879	            {
880	                onMessageCallback(_decompressedMessage, wireSize, false, messageKind);
881	            }
882	        }
883	        else
884	        {
885	            if (messageKind == MessageKind::MSG_TEXT && !validateUtf8(message))
886	            {
887	                close(WebSocketCloseConstants::kInvalidFramePayloadData,
888	                      WebSocketCloseConstants::kInvalidFramePayloadDataMessage);
889	            }
890	            else
891	            {
892	                onMessageCallback(message, wireSize, false, messageKind);
893	            }
894	        }
895	    }
