897	    unsigned WebSocketTransport::getRandomUnsigned()
898	    {
899	        auto now = std::chrono::system_clock::now();
900	        auto seconds =
901	            std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();
902	        return static_cast<unsigned>(seconds);
