1248	    void WebSocketTransport::closeSocketAndSwitchToClosedState(uint16_t code,
1249	                                                               const std::string& reason,
1250	                                                               size_t closeWireSize,
1251	                                                               bool remote)
1252	    {
1253	        closeSocket();
1254	
1255	        setCloseReason(reason);
1256	        _closeCode = code;
1257	        _closeWireSize = closeWireSize;
1258	        _closeRemote = remote;
1259	
1260	        setReadyState(ReadyState::CLOSED);
1261	        _requestInitCancellation = false;
1262	    }
1263	
1264	    void WebSocketTransport::close(uint16_t code,
1265	                                   const std::string& reason,
1266	                                   size_t closeWireSize,
1267	                                   bool remote)
1268	    {
1269	        _requestInitCancellation = true;
1270	
1271	        if (_readyState == ReadyState::CLOSING || _readyState == ReadyState::CLOSED)
1272	        {
1273	            // Wake up the socket polling thread, as
1274	            // Socket::isReadyToRead() might be still waiting the
1275	            // interrupt event to happen.
1276	            bool wakeUpPoll = false;
1277	            {
1278	              std::lock_guard<std::mutex> lock(_socketMutex);
1279	              wakeUpPoll = (_socket && _socket->isWakeUpFromPollSupported());
1280	            }
1281	            if (wakeUpPoll)
1282	            {
1283	                wakeUpFromPoll(SelectInterrupt::kCloseRequest);
1284	            }
1285	            return;
1286	        }
1287	
1288	        if (closeWireSize == 0)
1289	        {
1290	            closeWireSize = reason.size();
1291	        }
1292	
1293	        setCloseReason(reason);
1294	        _closeCode = code;
1295	        _closeWireSize = closeWireSize;
1296	        _closeRemote = remote;
1297	
1298	        {
1299	            std::lock_guard<std::mutex> lock(_closingTimePointMutex);
1300	            _closingTimePoint = std::chrono::steady_clock::now();
1301	        }
1302	        setReadyState(ReadyState::CLOSING);
1303	
1304	        sendCloseFrame(code, reason);
1305	
1306	        // wake up the poll, but do not close yet
1307	        wakeUpFromPoll(SelectInterrupt::kSendRequest);
1308	    }
