1314	    }
1315	
1316	    bool WebSocketTransport::flushSendBuffer()
1317	    {
1318	        auto start = std::chrono::steady_clock::now();
1319	
1320	        // timeoutMs tracks how long to wait before forcefully
1321	        // closing the socket when sending runs into a timeout.
1322	        std::chrono::seconds timeoutSecs(0);
1323	        if (_sendTimeoutSecs > 0)
1324	        {
1325	            timeoutSecs = std::chrono::seconds(_sendTimeoutSecs);
1326	        }
1327	        else if (_pingIntervalSecs > 0)
1328	        {
1329	            // If a pingInterval is set, use it as a timeout because if we cannot
1330	            // send out any data for pingInterval seconds, we may as well disconnet
1331	            // the client.
1332	            timeoutSecs = std::chrono::seconds(_pingIntervalSecs);
1333	        }
1334	
1335	        while (!isSendBufferEmpty() && !_requestInitCancellation)
1336	        {
1337	            // Wait with a 10ms timeout until the socket is ready to write.
1338	            // This way we are not busy looping
1339	            PollResultType result = _socket->isReadyToWrite(10);
1340	
1341	            if (result == PollResultType::Error)
1342	            {
1343	                closeSocket();
1344	                setReadyState(ReadyState::CLOSED);
1345	                return false;
1346	            }
1347	            else if (result == PollResultType::ReadyForWrite)
1348	            {
1349	                if (!sendOnSocket())
1350	                {
1351	                    return false;
1352	                }
1353	            }
1354	            else if (result == PollResultType::Timeout && timeoutSecs.count() > 0)
1355	            {
1356	                auto now = std::chrono::steady_clock::now();
1357	                // Timeout error and exceeded the allocated timeout: Treat
1358	                // as abnormal close and use "Send Timeout" for the reason.
1359	                if (now > start + timeoutSecs)
1360	                {
1361	                    closeSocketAndSwitchToClosedState(WebSocketCloseConstants::kAbnormalCloseCode,
1362	                                                      WebSocketCloseConstants::kSendTimeoutMessage,
1363	                                                      0,
1364	                                                      false);
1365	                    return false;
1366	                }
1367	            }
1368	        }
1369	
1370	        return true;
1371	    }
