611	    ReadyState WebSocket::getReadyState() const
612	    {
613	        switch (_ws.getReadyState())
614	        {
615	            case ix::WebSocketTransport::ReadyState::OPEN: return ReadyState::Open;
616	            case ix::WebSocketTransport::ReadyState::CONNECTING: return ReadyState::Connecting;
617	            case ix::WebSocketTransport::ReadyState::CLOSING: return ReadyState::Closing;
618	            case ix::WebSocketTransport::ReadyState::CLOSED: return ReadyState::Closed;
619	            default: return ReadyState::Closed;
620	        }
621	    }
622	
