29	    const int Socket::kDefaultPollNoTimeout = -1; // No poll timeout by default
30	    const int Socket::kDefaultPollTimeout = kDefaultPollNoTimeout;
31	
32	    Socket::Socket(int fd)
33	        : _sockfd(fd)
34	        , _selectInterrupt(createSelectInterrupt())
35	    {
36	        ;
37	    }
38	
39	    Socket::~Socket()
40	    {
41	        close();
42	    }
43	
44	    PollResultType Socket::poll(bool readyToRead,
45	                                int timeoutMs,
46	                                socket_t sockfd,
47	                                const SelectInterruptPtr& selectInterrupt)
48	    {
49	        PollResultType pollResult = PollResultType::ReadyForRead;
50	
51	        //
52	        // We used to use ::select to poll but on Android 9 we get large fds out of
53	        // ::connect which crash in FD_SET as they are larger than FD_SETSIZE. Switching
54	        // to ::poll does fix that.
55	        //
56	        // However poll isn't as portable as select and has bugs on Windows, so we
57	        // have a shim to fallback to select on those platforms. See
58	        // https://github.com/mpv-player/mpv/pull/5203/files for such a select wrapper.
59	        //
60	        nfds_t nfds = 1;
61	        struct pollfd fds[2];
62	        memset(fds, 0, sizeof(fds));
63	
64	        fds[0].fd = sockfd;
65	        fds[0].events = (readyToRead) ? POLLIN : POLLOUT;
66	
67	        // this is ignored by poll, but our select based poll wrapper on Windows needs it
68	        fds[0].events |= POLLERR;
69	
70	        // File descriptor used to interrupt select when needed
71	        int interruptFd = -1;
72	        void* interruptEvent = nullptr;
73	        if (selectInterrupt)
74	        {
75	            interruptFd = selectInterrupt->getFd();
76	            interruptEvent = selectInterrupt->getEvent();
77	
78	            if (interruptFd != -1)
79	            {
80	                nfds = 2;
81	                fds[1].fd = interruptFd;
82	                fds[1].events = POLLIN;
83	            }
84	            else if (interruptEvent == nullptr)
85	            {
86	                // Emulation mode: SelectInterrupt neither supports file descriptors nor events
87	
88	                // Check the selectInterrupt for requests before doing the poll().
89	                if (readSelectInterruptRequest(selectInterrupt, &pollResult))
90	                {
91	                    return pollResult;
92	                }
93	            }
94	        }
95	
96	        void* event = interruptEvent; // ix::poll will set event to nullptr if it wasn't signaled
97	        int ret = ix::poll(fds, nfds, timeoutMs, &event);
98	
99	        if (ret < 0)
100	        {
101	            pollResult = PollResultType::Error;
102	        }
103	        else if (ret == 0)
104	        {
105	            pollResult = PollResultType::Timeout;
106	            if (selectInterrupt && interruptFd == -1 && interruptEvent == nullptr)
107	            {
108	                // Emulation mode: SelectInterrupt neither supports fd nor events
109	
110	                // Check the selectInterrupt for requests
111	                readSelectInterruptRequest(selectInterrupt, &pollResult);
112	            }
113	        }
114	        else if ((interruptFd != -1 && fds[1].revents & POLLIN) || (interruptEvent != nullptr && event != nullptr))
115	        {
116	            // The InterruptEvent was signaled
117	            readSelectInterruptRequest(selectInterrupt, &pollResult);
118	        }
119	        else if (sockfd != -1 && readyToRead && fds[0].revents & POLLIN)
120	        {
121	            pollResult = PollResultType::ReadyForRead;
122	        }
123	        else if (sockfd != -1 && !readyToRead && fds[0].revents & POLLOUT)
124	        {
125	            pollResult = PollResultType::ReadyForWrite;
126	
127	#ifdef _WIN32
128	            // On connect error, in async mode, windows will write to the exceptions fds
129	            if (fds[0].revents & POLLERR)
130	            {
131	                pollResult = PollResultType::Error;
132	            }
133	#else
134	            int optval = -1;
135	            socklen_t optlen = sizeof(optval);
136	
137	            // getsockopt() puts the errno value for connect into optval so 0
138	            // means no-error.
139	            if (getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &optval, &optlen) == -1 || optval != 0)
140	            {
141	                pollResult = PollResultType::Error;
142	
143	                // set errno to optval so that external callers can have an
144	                // appropriate error description when calling strerror
145	                errno = optval;
146	            }
147	#endif
148	        }
149	        else if (sockfd != -1 && (fds[0].revents & POLLERR || fds[0].revents & POLLHUP ||
150	                                  fds[0].revents & POLLNVAL))
151	        {
152	            pollResult = PollResultType::Error;
153	        }
154	
155	        return pollResult;
156	    }
157	
158	    bool Socket::readSelectInterruptRequest(const SelectInterruptPtr& selectInterrupt,
159	                                            PollResultType* pollResult)
160	    {
161	        uint64_t value = selectInterrupt->read();
162	
163	        if (value == SelectInterrupt::kSendRequest)
164	        {
165	            *pollResult = PollResultType::SendRequest;
166	            return true;
167	        }
168	        else if (value == SelectInterrupt::kCloseRequest)
169	        {
170	            *pollResult = PollResultType::CloseRequest;
171	            return true;
172	        }
173	
174	        return false;
175	    }
176	
177	    PollResultType Socket::isReadyToRead(int timeoutMs)
178	    {
179	        if (_sockfd == -1)
180	        {
181	            return PollResultType::Error;
182	        }
183	
184	        bool readyToRead = true;
185	        return poll(readyToRead, timeoutMs, _sockfd, _selectInterrupt);
186	    }
187	
188	    PollResultType Socket::isReadyToWrite(int timeoutMs)
189	    {
190	        if (_sockfd == -1)
191	        {
192	            return PollResultType::Error;
193	        }
194	
195	        bool readyToRead = false;
196	        return poll(readyToRead, timeoutMs, _sockfd, _selectInterrupt);
197	    }
