111	        //
112	        // 7.2.1.  Compression
113	        //
114	        //    An endpoint uses the following algorithm to compress a message.
115	        //
116	        //    1.  Compress all the octets of the payload of the message using
117	        //        DEFLATE.
118	        //
119	        //    2.  If the resulting data does not end with an empty DEFLATE block
120	        //        with no compression (the "BTYPE" bits are set to 00), append an
121	        //        empty DEFLATE block with no compression to the tail end.
122	        //
123	        //    3.  Remove 4 octets (that are 0x00 0x00 0xff 0xff) from the tail end.
124	        //        After this step, the last octet of the compressed data contains
125	        //        (possibly part of) the DEFLATE header bits with the "BTYPE" bits
126	        //        set to 00.
127	        //
128	        size_t output;
129	
130	        // Clear output
131	        out.clear();
132	
133	        if (in.empty())
134	        {
135	            // See issue #167
136	            // The normal buffer size should be 6 but
137	            // we remove the 4 octets from the tail (#4)
138	            uint8_t buf[2] = {0x02, 0x00};
139	            out.push_back(buf[0]);
140	            out.push_back(buf[1]);
141	
142	            return true;
143	        }
144	
145	        _deflateState.avail_in = (uInt) in.size();
146	        _deflateState.next_in = (Bytef*) in.data();
147	
148	        do
149	        {
150	            // Output to local buffer
151	            _deflateState.avail_out = (uInt) _compressBuffer.size();
152	            _deflateState.next_out = &_compressBuffer.front();
153	
154	            deflate(&_deflateState, _flush);
155	
156	            output = _compressBuffer.size() - _deflateState.avail_out;
157	
158	            out.insert(out.end(), _compressBuffer.begin(), _compressBuffer.begin() + output);
159	        } while (_deflateState.avail_out == 0);
160	
161	        if (endsWithEmptyUnCompressedBlock(out))
162	        {
163	            out.resize(out.size() - 4);
164	        }
165	
166	        return true;
167	#else
168	        (void) in;
169	        (void) out;
170	        return false;
171	#endif
