WebSocketSendInfo WebSocketTransport::sendData(wsheader_type::opcode_type type,
                                               const IXWebSocketSendData& message,
                                               bool compress,
                                               const OnProgressCallback& onProgressCallback)
{
    // Data frames can only be sent on an open connection. Control frames
    // (close, ping, pong) can still be emitted while the connection is
    // closing, to complete the closing handshake.
    bool isDataFrame = type == wsheader_type::TEXT_FRAME ||
                       type == wsheader_type::BINARY_FRAME ||
                       type == wsheader_type::CONTINUATION;
    if (_readyState != ReadyState::OPEN &&
        (_readyState != ReadyState::CLOSING || isDataFrame))
    {
        return WebSocketSendInfo(false);
    }

    size_t payloadSize = message.size();
    size_t wireSize = message.size();
    bool compressionError = false;

    auto message_begin = message.cbegin();
    auto message_end = message.cend();

    if (compress)
    {
        if (!_perMessageDeflate->compress(message, _compressedMessage))
        {
            bool success = false;
            compressionError = true;
            payloadSize = 0;
            wireSize = 0;
            return WebSocketSendInfo(success, compressionError, payloadSize, wireSize);
        }
        compressionError = false;
        wireSize = _compressedMessage.size();

        IXWebSocketSendData compressedSendData(_compressedMessage);
        message_begin = compressedSendData.cbegin();
        message_end = compressedSendData.cend();
    }

    {
        std::lock_guard<std::mutex> lock(_txbufMutex);
        _txbuf.reserve(wireSize);
    }

    bool success = true;
    bool cancelled = false;

    // Common case for most message. No fragmentation required.
    if (wireSize < kChunkSize)
    {
        success = sendFragment(type, true, message_begin, message_end, compress);

        if (onProgressCallback)
        {
            // The message was fully committed to the send buffer (this
            // is the only fragment), so the return value of the
            // progress callback cannot cancel anything here.
            onProgressCallback(0, 1);
        }
    }
    else
    {
