            TLogger() << "server error log: " << errors[0];
            REQUIRE(errors[0].find("tls accept failed") != std::string::npos);
            REQUIRE(errors[0].find("127.0.0.1") != std::string::npos);
        }

        server.stop();
        REQUIRE(server.getClients().size() == 0);
    }
#endif
}

